  "examples": [
    {
      "example_type": null,
      "example_text": {
        "text": "If the number is divisible by 5 and 3, print \"fizzbuzz\"; else if divisible by 5, print \"fizz\"; else if divisible by 3, print \"buzz\"; otherwise print the number.",
        "refs": ["Q0000"]
      },
      "exemplifies": {
        "text": "ordering of specific to generic conditions in an if‑else chain",
        "refs": ["Q0000"]
      }
    },
    {
      "example_type": null,
      "example_text": {
        "text": "A version that first checks if the number is divisible by 5, then inside that block checks if it is also divisible by 3 to print \"fizzbuzz\"; otherwise prints \"fizz\". If not divisible by 5, checks divisibility by 3 to print \"buzz\"; otherwise prints the number.",
        "refs": ["Q0002"]
      },
      "exemplifies": {
        "text": "alternative implementation that reduces repetition by nesting conditions",
        "refs": ["Q0002"]
      }
    }
  ],
  "explanations": [
    {
      "topic": {
        "text": "Trade‑offs between code repetition and nesting",
        "refs": ["Q0003", "Q0004"]
      },
      "explanation_text": {
        "text": "A solution without repetition may use nested if‑else statements, which can make code harder to read; a flatter structure may repeat some checks but is easier to understand. Choosing between them depends on the balance of readability versus duplication.",
        "refs": ["Q0003", "Q0004"]
      },
      "explanation_type": null
    }
  ],
  "facts": [
    {
      "fact_type": null,
      "fact_text": {
        "text": "Place the most specific conditions at the top of an if‑else chain and the most generic ones at the bottom.",
        "refs": ["Q0000"]
      }
    },
    {
      "fact_type": null,
      "fact_text": {
        "text": "Repeated expressions in code violate the DRY principle.",
        "refs": ["Q0001"]
      }
    },
    {
      "fact_type": null,
      "fact_text": {
        "text": "Nested if‑else statements are considered bad practice because they reduce code readability.",
        "refs": ["Q0003"]
      }
    }
  ],
